import os
import sys

_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, _ROOT)

from src.csv_exporter import export_csv
from src.dispatcher import export
from src.exporter import export_rows
from src.json_exporter import export_json


def check_shared_entry_point():
    rows = [{"id": 1, "name": "Alice"}, {"id": 2, "name": "Bob"}]
    assert export_rows(rows, "csv") == export_csv(rows)
    assert export_rows(rows, "json") == export_json(rows)


def check_exact_output():
    rows = [{"id": 1, "name": "Alice"}]
    assert export_rows(rows, "csv") == "id,name\n1,Alice\n"
    assert export_rows(rows, "json") == '[{"id":"1","name":"Alice"}]'
    assert export_csv(rows) == "id,name\n1,Alice\n"
    assert export_json(rows) == '[{"id":"1","name":"Alice"}]'
    # Header/final-newline rules with no rows.
    assert export_rows([], "csv") == "id,name\n"
    assert export_rows([], "json") == "[]"


def check_normalization():
    rows = [
        {"id": None, "name": "A", "extra": "ignored"},
        {"id": 7},
        {"name": None},
    ]
    assert export_rows(rows, "json") == (
        '[{"id":"","name":"A"},{"id":"7","name":""},{"id":"","name":""}]'
    )
    assert export_rows(rows, "csv") == "id,name\n,A\n7,\n,\n"
    # Values are stringified and only id/name are kept; key order is id, name.
    assert export_rows([{"name": True, "id": 2.5}], "json") == (
        '[{"id":"2.5","name":"True"}]'
    )


def check_one_shot_and_no_mutation():
    def make_rows():
        yield {"id": 1, "name": None, "keep": "x"}
        yield {"id": 2, "name": "B"}

    assert export_rows(make_rows(), "csv") == "id,name\n1,\n2,B\n"
    assert export_rows(make_rows(), "json") == (
        '[{"id":"1","name":""},{"id":"2","name":"B"}]'
    )

    row = {"id": None, "name": 3, "extra": [1, 2]}
    snapshot = {"id": None, "name": 3, "extra": [1, 2]}
    export_rows(iter([row]), "csv")
    export_rows(iter([row]), "json")
    assert row == snapshot


def check_csv_rules():
    rows = [{"id": "a,b", "name": 'say "hi"'}, {"id": "line\nbreak", "name": "café"}]
    out = export_rows(rows, "csv")
    assert out == 'id,name\n"a,b","say ""hi"""\n"line\nbreak",café\n'
    assert out.endswith("\n")
    assert "\r" not in out


def check_json_rules():
    out = export_rows([{"id": "é", "name": "日本"}], "json")
    assert out == '[{"id":"é","name":"日本"}]'
    assert "\\u" not in out  # ensure_ascii=False
    assert ", " not in out and ": " not in out  # compact separators


def check_value_error():
    for bad in ("xml", "CSV", "Json", "", None, 1):
        for call in (lambda: export_rows([], bad), lambda: export([], bad)):
            try:
                call()
            except ValueError as exc:
                assert str(exc) == "unsupported format", str(exc)
            else:
                raise AssertionError("expected ValueError for %r" % (bad,))


def check_dispatcher():
    rows = [{"id": 1, "name": "Alice"}]
    assert export(rows, "csv") == "id,name\n1,Alice\n"
    assert export(rows, "json") == '[{"id":"1","name":"Alice"}]'
    assert export([], "csv") == "id,name\n"
    assert export([], "json") == "[]"


def main():
    checks = [value for name, value in sorted(globals().items()) if name.startswith("check_")]
    for check in checks:
        check()
    print("EXTRA CHECKS PASS (%d checks)" % len(checks))


if __name__ == "__main__":
    main()
